using namespace std;

class Solution {
    vector<int> parent;
    int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }
    void unite(int x, int y) {
        int rx = find(x), ry = find(y);
        if (rx != ry) parent[rx] = ry;
    }
public:
    vector<bool> distanceLimitedPathsExist(int n, vector<vector<int>>& edgeList, vector<vector<int>>& queries) {
        parent.resize(n);
        iota(parent.begin(), parent.end(), 0);
        sort(edgeList.begin(), edgeList.end(), [](const vector<int>& a, const vector<int>& b) {
            return a[2] < b[2];
        });
        int q_size = queries.size();
        vector<int> q_idx(q_size);
        iota(q_idx.begin(), q_idx.end(), 0);
        sort(q_idx.begin(), q_idx.end(), [&](int a, int b) {
            return queries[a][2] < queries[b][2];
        });
        vector<bool> res(q_size, false);
        int e_idx = 0, m = edgeList.size();
        for (int idx : q_idx) {
            int limit = queries[idx][2];
            while (e_idx < m && edgeList[e_idx][2] < limit) {
                unite(edgeList[e_idx][0], edgeList[e_idx][1]);
                e_idx++;
            }
            res[idx] = (find(queries[idx][0]) == find(queries[idx][1]));
        }
        return res;
    }
};

import java.util.*;

class Solution {
    private int[] parent;
    private int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }
    private void union(int x, int y) {
        int rx = find(x), ry = find(y);
        if (rx != ry) parent[rx] = ry;
    }

    public boolean[] distanceLimitedPathsExist(int n, int[][] edgeList, int[][] queries) {
        parent = new int[n];
        for (int i = 0; i < n; ++i) parent[i] = i;
        Arrays.sort(edgeList, Comparator.comparingInt(a -> a[2]));
        int qSize = queries.length;
        Integer[] qIdx = new Integer[qSize];
        for (int i = 0; i < qSize; ++i) qIdx[i] = i;
        Arrays.sort(qIdx, Comparator.comparingInt(a -> queries[a][2]));
        boolean[] res = new boolean[qSize];
        int eIdx = 0, m = edgeList.length;
        for (int idx : qIdx) {
            int limit = queries[idx][2];
            while (eIdx < m && edgeList[eIdx][2] < limit) {
                union(edgeList[eIdx][0], edgeList[eIdx][1]);
                eIdx++;
            }
            res[idx] = (find(queries[idx][0]) == find(queries[idx][1]));
        }
        return res;
    }
}

/**
 * @param {number} n
 * @param {number[][]} edgeList
 * @param {number[][]} queries
 * @return {boolean[]}
 */
var distanceLimitedPathsExist = function(n, edgeList, queries) {
    const parent = Array.from({ length: n }, (_, i) => i);
    function find(x) {
        if (parent[x] !== x) parent[x] = find(parent[x]);
        return parent[x];
    }
    function union(x, y) {
        const rx = find(x), ry = find(y);
        if (rx !== ry) parent[rx] = ry;
    }

    edgeList.sort((a, b) => a[2] - b[2]);
    const qIdx = Array.from({ length: queries.length }, (_, i) => i);
    qIdx.sort((a, b) => queries[a][2] - queries[b][2]);
    const res = Array(queries.length).fill(false);
    let eIdx = 0, m = edgeList.length;

    for (const idx of qIdx) {
        const limit = queries[idx][2];
        while (eIdx < m && edgeList[eIdx][2] < limit) {
            union(edgeList[eIdx][0], edgeList[eIdx][1]);
            eIdx++;
        }
        res[idx] = (find(queries[idx][0]) === find(queries[idx][1]));
    }
    return res;
};
